\title{The Splitting-Type Channel of a Cyclic Field:\\
Exact Values, CRT Additivity, and the Failure of the One-Bit Cap}
\author{Aristotle}
\date{15 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $f$ be a prime and let $\QQ(\zeta_f)$ be the $f$-th cyclotomic field, whose Galois group is cyclic of order $n=f-1$. For an unramified prime $p$ the \emph{splitting type} $T(p)=\ord_f(p)$ --- the residue degree, equivalently the order of the Frobenius element $p \bmod f$ --- is a multi-state random variable taking each divisor $d \mid n$ with rate $\varphi(d)/n$. We study the \emph{type-pair channel} of a semiprime $N=pq$: the mutual information between the visible residue $N \bmod f$ and the unordered pair $\{T(p),T(q)\}$, denoted $\Ipair(n)$. We prove that the single-prime channel is lossless and unaffected by refining the modulus; that $\Ipair$ is additive over coprime factorisations, hence determined by prime-power atoms; that prime atoms admit the closed form $\Ipair(p)=\log_2 p-\frac{(p-1)(2p-1)}{p^{2}}\log_2(p-1)+\frac{(p-1)(p-2)}{p^{2}}\log_2(p-2)$, from which $\Ipair(p)=1$ exactly at $p=2$ and any order above one bit is composite; and that $\Ipair(4)=5/4$, $\Ipair(6)=\log_2 3-1/9$, $\Ipair(12)=5/36+\log_2 3$, $\Ipair(16)=85/64$ all exceed the one-bit cap of the binary symmetric fork. We exhibit infinite above-cap families ($\Ipair(4m)\ge 5/4$ for every odd $m$) and an \emph{odd} above-cap order $M=300\,840\,735\,195$, refuting the hypothesis that an element of order two is responsible. We establish the geometric ladder $\Ipair(2^{k})=\frac43(1-4^{-k})$ for $k\le 5$, the strict lossiness of the binary root-count readout (whose entropy is pinned to $H(1/n)$), and the vanishing of the which-factor wall: the unordered channel equals the ordered one, so all leakage is symmetric.
\end{abstract}

\noindent\textbf{Keywords:} cyclotomic field, splitting type, residue degree, Frobenius, mutual information, Euler totient, Chinese Remainder Theorem, semiprime.

\section{Introduction}

\subsection{The problem}
Fix an arithmetic invariant $\chi$ of a prime, form a semiprime $N=pq$, and ask how many bits the visible quantity $N$ reveals about the pair $(\chi(p),\chi(q))$. When $\chi$ is binary the answer is bounded by one bit, and in the symmetric case --- where only the unordered pair is observable --- the bound is attained. This \emph{one-bit binary-fork cap} has been the standing ceiling for symmetric semiprime channels.

The observation driving this paper is that the cap is a property of \emph{binary} invariants, not of semiprimes and not of symmetry. There is a canonical, arithmetically complete, multi-state invariant attached to a prime in a cyclic field: its splitting type. We compute its semiprime pair channel exactly and find that the cap fails, quantitatively and structurally.

\subsection{Setting}
Let $f$ be a prime, $\zeta_f$ a primitive $f$-th root of unity, and $K=\QQ(\zeta_f)$. Then $\operatorname{Gal}(K/\QQ)\cong(\ZZ/f)^{\times}$ is cyclic of order $n=f-1$. For a prime $p\ne f$ the Frobenius class is the singleton $\{p \bmod f\}$ and
\[
p\mathcal{O}_K=\mathfrak{p}_1\cdots\mathfrak{p}_g,\qquad g=\frac{n}{T(p)},\qquad T(p):=\ord_f(p),
\]
with each $\mathfrak{p}_i$ of residue degree $T(p)$. Thus $T(p)$ is the complete splitting type. Since $T(p)$ depends only on $p\bmod f$ and residues equidistribute (Dirichlet; Chebotarev in general), the correct model is a finite counting model: choose the Frobenius exponent uniformly in $\ZZ/n$ and read off the type. All results below are exact statements about that finite model.

\section{The counting-entropy framework}
Throughout $S$ is a finite nonempty set and a \emph{readout} is a function $g:S\to B$. All entropies are in bits.

\begin{definition}[Counting entropy]
$\displaystyle H_S(g)=\log_2|S|-\frac{1}{|S|}\sum_{a\in S}\log_2\bigl|g^{-1}(g(a))\bigr|.$
\end{definition}

\begin{proposition}[Shannon form]
$H_S(g)=-\sum_{v\in g(S)}\pi_v\log_2\pi_v$ with $\pi_v=|g^{-1}(v)|/|S|$.
\end{proposition}
\begin{proof}[Proof sketch]
Group the sum over $a$ by the value $v=g(a)$; each fibre contributes $|g^{-1}(v)|\log_2|g^{-1}(v)|$. Divide by $|S|$ and use $\log_2\pi_v=\log_2|g^{-1}(v)|-\log_2|S|$ together with $\sum_v\pi_v=1$.
\end{proof}

\begin{definition}[Conditional entropy, mutual information]
For readouts $g:S\to B$, $k:S\to C$,
\[
H_S(g\mid k)=\sum_{c\in k(S)}\frac{|k^{-1}(c)|}{|S|}H_{k^{-1}(c)}(g),\qquad
I_S(g;k)=H_S(g)-H_S(g\mid k).
\]
\end{definition}

\begin{proposition}[Basic structure]\label{prop:basic}
\emph{(a)} $H_S(g)\ge 0$; \emph{(b)} $H_S(g)\le\log_2|S|$; \emph{(c)} data processing: $H_S(h\circ g)\le H_S(g)$ and $H_S(h\circ g\mid k)\le H_S(g\mid k)$; \emph{(d)} $I_S(g;k)\ge 0$; \emph{(e)} if $k$ is injective on $S$ then $H_S(g\mid k)=0$ and $I_S(g;k)=H_S(g)$.
\end{proposition}
\begin{proof}[Proof sketch]
(a),(b) follow termwise from $1\le|g^{-1}(g(a))|\le|S|$. (c) each fibre of $h\circ g$ is a union of fibres of $g$, and $H$ decreases as fibres grow; the conditional version averages this inside each fibre of $k$ with non-negative weights. (d) conditioning refines fibres. (e) fibres of an injective $k$ are singletons.
\end{proof}

\begin{proposition}[Product additivity]\label{prop:prod}
If $S=S_1\times S_2$ and $g=(g_1,g_2)$, $k=(k_1,k_2)$ act coordinatewise, then $H$, $H(\cdot\mid\cdot)$ and $I$ are the sums of the corresponding quantities on $S_1$ and $S_2$.
\end{proposition}
\begin{proof}[Proof sketch]
The fibre of a coordinatewise readout over a product is the product of the fibres, so its $\log_2$ splits additively and the average over $S$ splits accordingly; for the conditional statement, the fibres of $k$ are products and the weights factor.
\end{proof}

\begin{proposition}[Invariance]\label{prop:inv}
$H$, $H(\cdot\mid\cdot)$ and $I$ are unchanged by injective recodings of either readout and by relabellings of $S$ along a compatible bijection.
\end{proposition}

\section{The splitting type as a finite object}

\begin{definition}
For $n\ge 1$ and $a\in\ZZ$ set $T_n(a)=n/\gcd(a,n)$.
\end{definition}

\begin{proposition}[Faithfulness of the exponent model]
Let $f$ be prime, $n=f-1$. There is a generator $g$ of $(\ZZ/f)^{\times}$ of order $n$ such that every unit is $g^{a}$ for a unique $a<n$, and $\ord(g^{a})=T_n(a)$.
\end{proposition}
\begin{proof}[Proof sketch]
$(\ZZ/f)^{\times}$ is cyclic of order $n$. In any finite group $\ord(g^{a})=\ord(g)/\gcd(a,\ord(g))=T_n(a)$, and $T_n$ is invariant under reduction of $a$ modulo $n$.
\end{proof}

\begin{proposition}[Type-count law]\label{prop:count}
For $n>0$ and $d\mid n$, $\#\{a\in\ZZ/n: T_n(a)=d\}=\varphi(d)$, and the realised types are exactly the divisors of $n$.
\end{proposition}
\begin{proof}[Proof sketch]
$T_n(a)=d$ iff $\gcd(a,n)=n/d$ iff $a=(n/d)b$ with $b<d$, $\gcd(b,d)=1$; there are $\varphi(d)$ such $b$.
\end{proof}

\begin{theorem}[Euler-totient entropy law]
For $n>0$,
\[
H(T)\;=\;\sum_{d\mid n}\frac{\varphi(d)}{n}\log_2\frac{n}{\varphi(d)}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Combine the Shannon form with Proposition~\ref{prop:count}.
\end{proof}

Sample values: $H(T)=1$ at $n=2$; $3/2$ at $n=4$ (rates $\tfrac14,\tfrac14,\tfrac12$ on types $1,2,4$); $\tfrac13+\log_2 3\approx 1.9183$ at $n=6$; $7/4$ at $n=8$; $\tfrac56+\log_2 3\approx 2.4183$ at $n=12$; $15/8$ at $n=16$.

\begin{theorem}[Losslessness]
$I(a;T_n)=H(T)$: the residue determines the type exactly.
\end{theorem}
\begin{proof}[Proof sketch]
The conditioning variable is the identity, which is injective; apply Proposition~\ref{prop:basic}(e).
\end{proof}

\begin{theorem}[Thickening zero]
For any readout injective on $\ZZ/n$ --- in particular $a\mapsto a\bmod nm$, i.e.\ observing $p$ modulo $f^{2}$ or any multiple of $f$ --- the type channel equals $H(T)$. Moreover $T_n(a\bmod nm)=T_n(a)$.
\end{theorem}
\begin{proof}[Proof sketch]
Same injectivity argument; invariance holds because $\gcd(a\bmod nm,n)=\gcd(a,n)$ when $n\mid nm$.
\end{proof}

\section{Coarsenings and their exact losses}

\begin{definition}
The \emph{root-count readout} is $\nr_n(T)=n$ if $T=1$ and $0$ otherwise (the binary flag ``$p$ splits completely''). The \emph{split-count projection} of an unordered type pair $\{t_1,t_2\}$ is $s=[t_1=1]+[t_2=1]\in\{0,1,2\}$.
\end{definition}

\begin{theorem}[Root-count entropies; quartic pinning]
\[
H(\nr_4)=2-\tfrac34\log_2 3=H(1/4)\approx 0.8113,\qquad
H(\nr_6)=1+\log_2 3-\tfrac56\log_2 5=H(1/6)\approx 0.6500,
\]
where $H(x)=-x\log_2 x-(1-x)\log_2(1-x)$; both are strictly below the corresponding type entropies $3/2$ and $\tfrac13+\log_2 3$.
\end{theorem}
\begin{proof}[Proof sketch]
Exactly one exponent, $a=0$, has type $1$, so the readout is binary with rates $(1/n,1-1/n)$ and $H(\nr_n)=H(1/n)$. Strictness follows from $\log_2 3>19/12$ and $\log_2 5>23/10$, i.e.\ from $3^{12}>2^{19}$ and $5^{10}>2^{23}$.
\end{proof}

\section{The type-pair channel}

\begin{definition}
Let $B_n=(\ZZ/n)\times(\ZZ/n)$ be the box of exponent pairs, uniformly distributed. Put
\[
\tp_n(a,b)=\{T_n(a),T_n(b)\}\ \text{(unordered)},\qquad \rho_n(a,b)=a+b\bmod n,
\]
the latter being the exponent of the visible semiprime, since Frobenius exponents add. The \emph{type-pair channel} is $\Ipair(n)=I_{B_n}(\tp_n;\rho_n)$, equivalently
\[
\Ipair(n)=H(\Pi)-\frac1n\sum_{c\in\ZZ/n}H(\Pi_c),
\]
$\Pi$ the law of the unordered pair and $\Pi_c$ its law conditioned on $a+b\equiv c$. The \emph{split-count channel} is $I_s(n)=I_{B_n}(s\circ\tp_n;\rho_n)$.
\end{definition}

\subsection{The which-factor wall}

\begin{theorem}[Symmetrisation is free]\label{thm:sym}
Since $\tp_n$ and $\rho_n$ are both symmetric in the two factors, the entropy defect of forgetting the order is the same with and without conditioning on $\rho_n$; therefore $\Ipair(n)$ equals the \emph{ordered} pair channel $I_{B_n}\bigl((T_n(a),T_n(b));\rho_n\bigr)$. The which-factor wall is exactly $0$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $\sigma$ be the swap involution. The unordered fibre over $\{t_1,t_2\}$ with $t_1\ne t_2$ is the disjoint union of the ordered fibre over $(t_1,t_2)$ and its $\sigma$-image, of equal cardinality; diagonal fibres are unchanged. Hence $H$ differs from the ordered entropy by the off-diagonal mass times one bit. Because $\rho_n\circ\sigma=\rho_n$, the identical computation applies inside each fibre of $\rho_n$, and the two defects cancel in the difference defining $I$.
\end{proof}

