\begin{corollary}[Failure of the one-bit cap]
$\Ipair(n)>1$ for $n\in\{4,6,8,10,12,14,16,18,20,32\}$, while $\Ipair(2)=1$ exactly and $\Ipair(n)<1$ for $n\in\{3,5,7,9,11,13,15,27\}$.
\end{corollary}
\begin{proof}[Proof sketch]
Substitute the closed forms and use certified rational enclosures of the logarithms: $\tfrac{19}{12}<\log_2 3<\tfrac{27}{17}$, $\tfrac{23}{10}<\log_2 5<\tfrac73$, $\tfrac{14}{5}<\log_2 7<3$, $\log_2 11<\tfrac72$, $\log_2 13<\tfrac{15}{4}$; each comparison becomes a linear inequality over $\QQ$.
\end{proof}

\begin{remark}[Divisor richness, not size]
The maximum among the computed orders is at $n=12$: $\Ipair(12)>\Ipair(m)$ for $m\in\{2,4,6,10,16\}$. The order $12$ has six divisors and hence six type states, whereas $16$ has five. Richness of the divisor lattice, not the magnitude of $n$, governs the channel.
\end{remark}

\subsection{CRT additivity}

\begin{theorem}[Multiplicativity of the type]\label{thm:multT}
If $\gcd(m,n)=1$ then $T_{mn}(a)=T_m(a)T_n(a)$.
\end{theorem}
\begin{proof}[Proof sketch]
$\gcd(a,mn)=\gcd(a,m)\gcd(a,n)$, and division distributes accordingly.
\end{proof}

\begin{lemma}[Unique coprime splitting]\label{lem:unique}
If $x,x'\mid m$, $y,y'\mid n$, $\gcd(m,n)=1$ and $xy=x'y'$, then $x=x'$ and $y=y'$.
\end{lemma}
\begin{proof}[Proof sketch]
$\gcd(xy,m)=x$ since $y$ is coprime to $m$ and $x\mid m$; likewise for $x'$.
\end{proof}

\begin{theorem}[CRT additivity]\label{thm:crt}
For coprime $m,n>0$, $\ \Ipair(mn)=\Ipair(m)+\Ipair(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:sym} we may use the ordered pair channel. The map $(a,b)\mapsto\bigl((a\bmod m,b\bmod m),(a\bmod n,b\bmod n)\bigr)$ is a bijection $B_{mn}\to B_m\times B_n$ (injective by the Chinese Remainder criterion, surjective by cardinality). Under it, the ordered type readout becomes the coordinatewise readout by Theorem~\ref{thm:multT} and the injective recoding of Lemma~\ref{lem:unique}, and the residue readout becomes the coordinatewise pair of residues. Conclude with Propositions~\ref{prop:inv} and \ref{prop:prod}.
\end{proof}

\begin{corollary}[Prime-power decomposition]
For $n\ne 0$, $\ \Ipair(n)=\sum_{p\mid n}\Ipair\bigl(p^{v_p(n)}\bigr)$, and $\Ipair(1)=0$.
\end{corollary}

\begin{corollary}[Doubling law]
For odd $m>0$, $\ \Ipair(2m)=\Ipair(m)+1$.
\end{corollary}

\subsection{The prime orders}

\begin{theorem}[Prime closed form]\label{thm:prime}
For every prime $p$,
\[
\Ipair(p)=\log_2 p-\frac{(p-1)(2p-1)}{p^{2}}\log_2(p-1)+\frac{(p-1)(p-2)}{p^{2}}\log_2(p-2),
\]
with $0\log_2 0=0$ (relevant only at $p=2$, where the formula gives $1$).
\end{theorem}
\begin{proof}[Proof sketch]
For $n=p$ prime, $T_p(a)=1$ if $a=0$ and $p$ otherwise, so the unordered pair takes three values with fibre sizes $1$, $2(p-1)$ and $(p-1)^{2}$ in a box of size $p^{2}$, whence
\[
H(\tp)=2\log_2 p-\frac{2(p-1)}{p^{2}}-\frac{2(p-1)\log_2(p-1)}{p}.
\]
Each residue class $c$ has exactly $p$ preimages forming a diagonal. On $c=0$ the pair distribution over the three values is $(1,0,p-1)$; on each $c\ne 0$ it is $(0,2,p-2)$. Averaging the entropies with equal weights and subtracting gives the stated expression.
\end{proof}

\begin{theorem}[Odd prime orders lie below the cap]
For every prime $p\ne 2$, $\Ipair(p)<1$; hence $\Ipair(p)=1$ iff $p=2$.
\end{theorem}
\begin{proof}[Proof sketch]
The leading $\log_2 p$ in Theorem~\ref{thm:prime} cancels against the leading term of the two logarithm sums; the residual is $O(1/p)$, controlled by the increment bound $\log_2(x+1)-\log_2 x\le 1/(x\ln 2)$ and $\log_2 p\le p$, and is below $1$ already at $p=3$.
\end{proof}

\begin{theorem}[Decay envelope]
For every odd prime $p$, $\ \Ipair(p)\le\dfrac{\log_2 p+3p}{p^{2}}$; in particular $\Ipair(p)\to 0$.
\end{theorem}

\begin{theorem}[Above the cap implies composite]
If $\Ipair(n)>1$ then $n$ is not prime.
\end{theorem}

\subsection{Infinite families}

\begin{theorem}[Non-negativity]
$\Ipair(n)\ge 0$ for all $n$.
\end{theorem}

\begin{theorem}[Above-cap families]
For every odd $m>0$,
\[
\Ipair(2m)\ge 1,\qquad \Ipair(4m)\ge\tfrac54,\qquad \Ipair(8m)\ge\tfrac{21}{16},\qquad \Ipair(16m)\ge\tfrac{85}{64}.
\]
In particular $\Ipair(4m)>1$ for every odd $m$.
\end{theorem}
\begin{proof}[Proof sketch]
$2^{j}$ is coprime to every odd $m$; apply Theorem~\ref{thm:crt} and drop the non-negative term $\Ipair(m)$.
\end{proof}

\begin{corollary}[Unboundedness]
For every $B$ there is $n>B$ with $\Ipair(n)>1$; take $n=4(2B+1)$.
\end{corollary}

\begin{theorem}[An odd order above the cap]
The odd number $M=9\cdot 5\cdot 7\cdot 11\cdot 13\cdot 17\cdot 19\cdot 23\cdot 29\cdot 31=300\,840\,735\,195$ satisfies $\Ipair(M)>1$.
\end{theorem}
\begin{proof}[Proof sketch]
Iterated CRT additivity splits $\Ipair(M)$ into ten primary contributions, each bounded below by an explicit rational obtained from the closed forms with certified logarithm bounds, e.g.\ $\Ipair(9)\ge\tfrac{21835}{41472}$, $\Ipair(5)\ge\tfrac{10371}{51200}$, $\Ipair(7)\ge\tfrac{2845}{25088}$. Their sum exceeds $1$.
\end{proof}

This refutes the hypothesis that an element of order two breaks the cap: evenness is sufficient but not necessary. What matters is accumulating enough independent primary parts.

\subsection{The prime-power ladders}

\begin{theorem}[$2$-adic ladder]
For $1\le k\le 5$,
\[
\Ipair(2^{k})=\frac{4}{3}\bigl(1-4^{-k}\bigr)=\frac{4^{k}-1}{3\cdot 4^{k-1}},
\]
giving $1,\tfrac54,\tfrac{21}{16},\tfrac{85}{64},\tfrac{341}{256}$; the increments are exactly $4^{-k}$; the sequence is strictly increasing and bounded above by $4/3$.
\end{theorem}

\begin{theorem}[$3$-adic ladder]
For $1\le k\le 3$, $\ \Ipair(3^{k})=(1-9^{-k})\cdot\tfrac98\cdot\Ipair(3)$, with increments $9^{-k}\Ipair(3)$ for $k\le 2$. In particular $\Ipair(27)\approx 0.5324<1$.
\end{theorem}

Both ladders match the shape $\Ipair(p^{k})=(1-p^{-2k})\frac{p^{2}}{p^{2}-1}\Ipair(p)$, conjectured in general below. The mechanism is $p$-adic self-similarity: in $(\ZZ/p^{k})^{2}$ the type of $a$ is $p^{\,k-v(a)}$ for the $p$-adic valuation $v$, off the diagonal $v(a+b)=\min(v(a),v(b))$, and the conditional law at each valuation level is a rescaled copy of the $p^{k-1}$ law.

\subsection{The split-count is one face}

\begin{theorem}[Split-count channel]
\[
I_s(4)=\tfrac{19}{8}-\tfrac{21}{16}\log_2 3\approx 0.2947,\qquad
I_s(6)=\tfrac{19}{9}+\log_2 3-\tfrac{55}{36}\log_2 5\approx 0.1487,
\]
and $I_s(n)<\Ipair(n)$ for $n=4,6$.
\end{theorem}
\begin{proof}[Proof sketch]
The $s$-projection is a deterministic coarsening of the type pair, so data processing gives $\le$; strictness follows from the exact values with the rational logarithm bounds. At $n=4$ the unconditional entropy of $s$ is $\tfrac{29}{8}-\tfrac32\log_2 3$ and the conditional entropy is $\tfrac54-\tfrac{3}{16}\log_2 3$.
\end{proof}

\begin{corollary}
At $n=4$ the root-count entropy is $\approx 0.811<1$ and the split-count channel is $\approx 0.295<1$, but the type-pair channel is $5/4>1$: the one-bit ceiling is a feature of binary readouts, not of the symmetric semiprime fork.
\end{corollary}

\section{Algorithms}

\paragraph{Exact channel by box enumeration.}
Given $n$: precompute $T(a)=n/\gcd(a,n)$ for $a<n$; for each $(a,b)$ increment the joint counter of the unordered pair and the conditional counter of the class $c=(a+b)\bmod n$; compute
$H(\Pi)=\log_2(n^{2})-\frac{1}{n^{2}}\sum_\tau \Pi[\tau]\log_2\Pi[\tau]$ and, since each slice has mass exactly $n$, $H(\Pi_c)=\log_2 n-\frac1n\sum_\tau\Pi_c[\tau]\log_2\Pi_c[\tau]$; return the difference of $H(\Pi)$ and the uniform average of $H(\Pi_c)$. Cost $O(n^{2})$. All counts being integers, the answer is a $\QQ$-linear combination of $1$ and logarithms of integers, reducible to the basis $\{1,\log_2 3,\log_2 5,\dots\}$ by factoring the counts; this is how the closed forms of Theorem~\ref{thm:table} are produced.

\paragraph{Fast channel by CRT reduction.}
Factor $n=\prod p_i^{k_i}$; evaluate each atom by the closed form when $k_i=1$ and by enumeration of the $p_i^{2k_i}$ box otherwise; sum. For squarefree $n$ the cost collapses to factoring plus $O(\omega(n))$ arithmetic --- indispensable for $M\approx 3\times 10^{11}$, whose direct box would have $\approx 9\times 10^{22}$ entries.

\paragraph{Certified logarithm bounds.}
$2^{A}\le q^{B}$ certifies $A/B\le\log_2 q$ and $q^{B}\le 2^{A}$ certifies $\log_2 q\le A/B$; each is a single integer comparison. From $3^{12}>2^{19}$ and $3^{17}<2^{27}$ one gets $\log_2 3\in(\tfrac{19}{12},\tfrac{27}{17})$, which suffices for every inequality here.

\section{Discussion}

The type-pair channel quantifies structural leakage: how much the residue of a semiprime constrains the joint splitting behaviour of its factors. It is a statement about the ensemble of semiprimes with a given visible residue, not about any individual factorisation. Because the which-factor wall vanishes, all leaked information is invariant under swapping $p$ and $q$ and can never separate them; and predicting which type pair occurs needs the two exponents separately, which is precisely what factoring would supply. These results therefore refine the picture of what is publicly determined without weakening any factoring-based assumption.

Why did the cap fail? The classical bound comes from a two-state readout in a symmetric fork. Nothing of that argument survives for a multi-state readout: instead of a single binary choice one has a divisor lattice, and the relevant question is how that lattice interacts with addition modulo $n$. CRT additivity makes this concrete --- the channel is a sum over primary parts, and any even primary part $\ge 4$ already contributes more than a full bit. It also explains the ordering anomalies: $\Ipair(12)>\Ipair(16)$ although $12<16$, because $\Ipair(12)=\tfrac54+\Ipair(3)$ and the prime atoms decay like $1/p$, making small primary parts the valuable ones.

The counting framework uses nothing about cyclotomic fields; any abelian extension with cyclic Galois group produces the same combinatorics via the Artin map, and the technique --- reduce to a finite exponent box, symmetrise for free, split along the CRT, decay-bound the atoms --- should transfer to genus theory, to non-abelian Frobenius shapes, and to products of more than two primes.

\section{Open problems}

\begin{conjecture}[Prime-power closed form]
For every prime $p$ and $k\ge 1$, $\ \Ipair(p^{k})=(1-p^{-2k})\dfrac{p^{2}}{p^{2}-1}\Ipair(p)$.
Established here for $p=2$, $k\le 5$ and $p=3$, $k\le 3$; numerically confirmed to $10^{-9}$ for $p=2$, $k\le 7$ and $p=3,5,7$, $k\le 3$.
\end{conjecture}

\begin{conjecture}[Supremum of the channel]
$\displaystyle \sup_n\Ipair(n)=\sum_{p}\frac{p^{2}}{p^{2}-1}\Ipair(p)$, convergent by the $O(1/p)$ envelope. Is it approached along primorials, and what is its value?
\end{conjecture}

\begin{problem}[Above-cap classification]
Characterise $\{n:\Ipair(n)>1\}$. Additivity reduces this to a knapsack over primary atoms; the two extremes are settled but the boundary is open.
\end{problem}

\begin{problem}[Non-abelian Frobenius shapes]
Replace the cyclic group by a general Galois group and the type by the Frobenius conjugacy class. Does an analogue of CRT additivity hold, and does the cap fail in the same way?
\end{problem}

\begin{problem}[$k$-almost-primes]
Extend to $N=p_1\cdots p_k$: the box becomes $(\ZZ/n)^{k}$, the readout the multiset of types, the conditioning variable the sum of exponents. Product additivity survives; symmetrisation needs the full symmetric group. How does the channel grow with $k$?
\end{problem}

\section{Conclusion}

The splitting type of a prime in a cyclic field is a complete, multi-state, totient-distributed invariant, determined exactly by a single residue and immune to modulus refinement. Its semiprime pair channel is additive over coprime factorisations, atomised by prime powers, closed-form at prime atoms, geometric at prime-power atoms, and strictly above the one-bit ceiling on infinitely many orders --- including odd ones. The classical split-count channel is recovered exactly as a small projection of it. The one-bit cap was never a law about semiprimes; it was a law about looking at them through a two-state window.

\end{document}

