"""CRT-accelerated evaluation of the type-pair channel.

Because the channel is additive over coprime factorisations, the value at an
arbitrary cyclic order is the sum of its prime-power atoms.  Prime atoms are
closed-form; prime-power atoms are enumerated in a box of size p^(2k), which is
tiny compared with the full n^2 box.
"""

from __future__ import annotations

from collections import Counter
from math import gcd, log2
from typing import Dict, List, Tuple


def factorise(n: int) -> Dict[int, int]:
    """Trial-division factorisation n = prod p^k."""
    factors: Dict[int, int] = {}
    d: int = 2
    m: int = n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors


def prime_atom(p: int) -> float:
    """Closed form I_pair(p) for a prime cyclic order p (with 0 log 0 = 0)."""
    if p == 2:
        return 1.0
    return (
        log2(p)
        - (p - 1) * (2 * p - 1) * log2(p - 1) / p**2
        + (p - 1) * (p - 2) * log2(p - 2) / p**2
    )


def enumerate_atom(q: int) -> float:
    """I_pair(q) for a prime power q, by direct enumeration of the q x q box."""
    types: List[int] = [q // gcd(a, q) for a in range(q)]
    joint: Counter = Counter()
    slices: Dict[int, Counter] = {c: Counter() for c in range(q)}
    for a in range(q):
        for b in range(q):
            tau: Tuple[int, int] = (min(types[a], types[b]), max(types[a], types[b]))
            joint[tau] += 1
            slices[(a + b) % q][tau] += 1

    def h(counts: List[int]) -> float:
        pos = [c for c in counts if c > 0]
        tot = sum(pos)
        return -sum((c / tot) * log2(c / tot) for c in pos) if tot else 0.0

    return h(list(joint.values())) - sum(
        h(list(s.values())) for s in slices.values()
    ) / q


def channel_fast(n: int) -> float:
    """I_pair(n) via the prime-power decomposition.

    Complexity: cost of factoring n, plus O(1) per prime atom and
    O(p^(2k)) per higher prime-power atom.  For squarefree n this is
    exponentially cheaper than the O(n^2) box enumeration.
    """
    if n <= 1:
        return 0.0
    total: float = 0.0
    for p, k in factorise(n).items():
        total += prime_atom(p) if k == 1 else enumerate_atom(p**k)
    return total


if __name__ == "__main__":
    M: int = 9 * 5 * 7 * 11 * 13 * 17 * 19 * 23 * 29 * 31
    print("M =", M, "odd:", M % 2 == 1)
    print("I_pair(M) =", channel_fast(M), "> 1:", channel_fast(M) > 1)
    for n in (12, 15, 20, 30, 210):
        print(n, round(channel_fast(n), 9))
